#### الگوی Slot با Children Props (روش دیگر):

```tsx
// ۲. الگوی Slots به عنوان Props (نه children)
interface CardSlots {
  header?: ReactNode;
  footer?: ReactNode;
  image?: ReactNode;
  actions?: ReactNode;
}

interface CardProps extends CardSlots {
  children: ReactNode;
}

function Card({ header, footer, image, actions, children }: CardProps) {
  return (
    <div className="card">
      {image && <div className="card-image">{image}</div>}
      {header && <div className="card-header">{header}</div>}
      <div className="card-content">{children}</div>
      {actions && <div className="card-actions">{actions}</div>}
      {footer && <div className="card-footer">{footer}</div>}
    </div>
  );
}

// استفاده:
<Card
  image={<img src="/product.jpg" />}
  header={<h3>محصول ویژه</h3>}
  footer={<p>قیمت: ۱۰۰ تومان</p>}
  actions={
    <>
      <Button>خرید</Button>
      <Button variant="ghost">ذخیره</Button>
    </>
