#### الگوی Slot با Composition (پیشرفته):

```tsx
// ۳. Dialog با Slotهای پیشرفته
function Dialog({ children }: { children: ReactNode }) {
  const [isOpen, setIsOpen] = useState(false);

  // یافتن Slotهای مختلف از children
  const trigger = findSlot(children, Dialog.Trigger);
  const title = findSlot(children, Dialog.Title);
  const content = findSlot(children, Dialog.Content);
  const actions = findSlot(children, Dialog.Actions);

  return (
    <>
      <div onClick={() => setIsOpen(true)}>{trigger}</div>

      {isOpen && (
        <Overlay onClose={() => setIsOpen(false)}>
          <div className="dialog">
            {title && <div className="dialog-title">{title}</div>}
            <div className="dialog-content">{content}</div>
            {actions && <div className="dialog-actions">{actions}</div>}
          </div>
        </Overlay>
      )}
    </>
  );
}

Dialog.Trigger = createSlot('Trigger');
Dialog.Title = createSlot('Title');
Dialog.Content = createSlot('Content');
Dialog.Actions = createSlot('Actions');

// استفاده:
<Dialog>
  <Dialog.Trigger>
    <Button>باز کردن</Button>
  </Dialog.Trigger>

  <Dialog.Title>
    <h2>حذف محصول</h2>
  </Dialog.Title>

  <Dialog.Content>
    <p>آیا از حذف این محصول مطمئن هستید؟</p>
    <WarningBanner>این عملیات قابل بازگشت نیست</WarningBanner>
  </Dialog.Content>

  <Dialog.Actions>
    <Button variant="danger">حذف</Button>
    <Button variant="ghost">انصراف</Button>
  </Dialog.Actions>
</Dialog>
```

