#### ۴. Promises کنسل نشده:

```tsx
// ❌ نشت: Promise بعد از unmount resolve می‌شود
function UserProfile({ userId }) {
  const [user, setUser] = useState(null);

  useEffect(() => {
    fetchUser(userId).then(setUser);
    // اگر userId عوض شود و fetch قبلی هنوز تمام نشده باشد:
    // ۱. fetch جدید شروع می‌شود
    // ۲. fetch قبلی resolve می‌شود و setUser را صدا می‌زند
    // ۳. state با داده قدیمی آپدیت می‌شود!
    // ۴. closure قدیمی در حافظه می‌ماند
  }, [userId]);
}

// ✅ درست: AbortController
useEffect(() => {
  const controller = new AbortController();

  fetchUser(userId, { signal: controller.signal })
    .then(setUser)
    .catch(err => {
      if (err.name !== 'AbortError') {
        console.error(err);
      }
    });

  return () => controller.abort();
}, [userId]);

// ✅ یا با React Query (توصیه شده):
function UserProfile({ userId }) {
  const { data: user } = useQuery({
    queryKey: ['user', userId],
    queryFn: () => fetchUser(userId),
    // React Query خودکار درخواست‌های قدیمی را نادیده می‌گیرد
  });
}
```

