#### ۵. Closureهای نگهدارنده State قدیمی (سناریوی پیشرفته):

```tsx
function Dashboard() {
  const [data, setData] = useState<LargeData[]>([]);
  const [filter, setFilter] = useState('');

  // ❌ نشت پیشرفته: هر رندر، یک data جدید + یک closure جدید
  const handleEvent = useCallback(() => {
    // این closure به data رفرنس دارد
    // حتی اگر کامپوننت رندر مجدد شود، closure قبلی:
    // ۱. data قدیمی را در حافظه نگه می‌دارد
    // ۲. اگر data بزرگ باشد (مثلاً ۱۰MB)، نشت قابل توجه است
    processData(data);
  }, [data]); // data هر بار تغییر می‌کند = closure جدید

  // ✅ راه‌حل: useRef برای داده بزرگ
  const dataRef = useRef(data);
  dataRef.current = data; // بدون رندر مجدد آپدیت می‌شود

  const handleEvent = useCallback(() => {
    processData(dataRef.current); // همیشه آخرین data
  }, []); // فقط یک closure!
}
```

---

#### ۶. نشت در Subscriptionهای پیچیده:

```tsx
// ❌ سناریوی واقعی: Observable با چند subscriber
function useObservable<T>(observable: Observable<T>) {
  const [value, setValue] = useState<T>();

  useEffect(() => {
    const subscription = observable.subscribe(setValue);
    return () => subscription.unsubscribe();
  }, [observable]);

  // ⚠️ اگر observable رفرنس جدید باشد، subscription قبلی:
  // ۱. unsubscribe می‌شود
  // ۲. اما observable قبلی هنوز ممکن است subscriberهای دیگری داشته باشد
  // ۳. کل زنجیره observable در حافظه می‌ماند
  return value;
}

// ✅ راه‌حل: استفاده از کتابخانه مناسب (RxJS با takeUntil)
function useObservable<T>(observable: Observable<T>) {
  const destroy$ = useRef(new Subject<void>());

  useEffect(() => {
    observable
      .pipe(takeUntil(destroy$.current))
      .subscribe(setValue);

    return () => {
      destroy$.current.next();
      destroy$.current.complete();
    };
  }, [observable]);
}
```

