#### ۸. سناریوی SPA طولانی مدت:

```tsx
// در اپلیکیشن‌های SPA که کاربر ساعت‌ها صفحه را باز نگه می‌دارد:

// ❌ مشکل: تجمع داده در stateهای global
const useAppStore = create((set) => ({
  notifications: [],
  addNotification: (notif) =>
    set((state) => ({
      notifications: [...state.notifications, notif],
    })),
  // این آرایه تا بی‌نهایت رشد می‌کند!
}));

// ✅ محدود کردن سایز:
const useAppStore = create((set) => ({
  notifications: [],
  addNotification: (notif) =>
    set((state) => ({
      notifications: [...state.notifications.slice(-100), notif],
