#### چک‌لیست جلوگیری از Memory Leak:

| منبع نشت | راه‌حل |
|----------|--------|
| Event Listeners | AbortController / cleanup |
| Intervals/Timeouts | clearInterval/clearTimeout در cleanup |
| WebSocket | close + handler = null |
| Promises | AbortController / React Query |
| Closure + Large Data | useRef + useCallback با deps خالی |
| DOM References | destroy در cleanup |
| تجمع داده | محدود کردن سایز آرایه‌ها |
| Observerها | disconnect در cleanup |

> **نکته تشخیص:** در Chrome DevTools → Memory tab → Take Heap Snapshot → مقایسه snapshotها قبل و بعد از mount/unmount. هر چیزی که بعد از unmount باقی مانده باشد، نشت حافظه است.

### استراتژی بهینه‌سازی لیست ۱۰۰,۰۰۰ تایی با Drag & Drop و فیلتر

این یک سناریوی ترکیبی با سه چالش است:
1. **حجم داده** (۱۰۰,۰۰۰ آیتم)
2. **رندر** (DOM زیاد = کند)
3. **تعامل** (Drag & Drop نیاز به پاسخ فوری)

---

#### استراتژی کلی (لایه‌ای):

```
لایه ۱: Virtualization ← فقط ۲۰-۳۰ آیتم در DOM
لایه ۲: Web Worker ← فیلتر و مرتب‌سازی خارج از Main Thread
لایه ۳: Memory Management ← کش هوشمند، Pagination مجازی
لایه ۴: Concurrent Mode ← اولویت‌بندی Drag & Drop بر رندر
```

---

#### پیاده‌سازی کامل:

```tsx
// ۱. Web Worker برای پردازش داده
// filter.worker.ts
interface WorkerMessage {
  type: 'FILTER' | 'SORT' | 'MOVE';
  payload: unknown;
}

let cachedItems: Item[] = [];

self.onmessage = (e: MessageEvent<WorkerMessage>) => {
  switch (e.data.type) {
    case 'FILTER': {
      const { items, query, filters } = e.data.payload;

      // فیلتر سنگین در Worker
      const filtered = items.filter(item => {
        return (
          fuzzyMatch(item.name, query) &&
          applyFilters(item, filters)
        );
      });

      // انتقال با Transferable Objects (سریع‌تر)
      self.postMessage({ type: 'FILTERED', data: filtered });
      break;
    }

    case 'MOVE': {
      const { fromIndex, toIndex, items } = e.data.payload;
      const newItems = [...items];
      const [moved] = newItems.splice(fromIndex, 1);
      newItems.splice(toIndex, 0, moved);
      self.postMessage({ type: 'MOVED', data: newItems });
      break;
    }
  }
};

// ۲. هوک سفارشی برای مدیریت داده
function useMassiveList(initialItems: Item[]) {
  const workerRef = useRef<Worker | null>(null);
  const [filteredItems, setFilteredItems] = useState<Item[]>([]);
  const [isProcessing, setIsProcessing] = useState(false);
  const processingRef = useRef(false);

  // State برای UI
  const [query, setQuery] = useState('');
  const deferredQuery = useDeferredValue(query); // Concurrent!

  useEffect(() => {
    workerRef.current = new Worker(
      new URL('./filter.worker.ts', import.meta.url)
    );

    workerRef.current.onmessage = (e) => {
      if (e.data.type === 'FILTERED') {
        setFilteredItems(e.data.data);
        setIsProcessing(false);
      }
    };

    return () => workerRef.current?.terminate();
  }, []);

  // فیلتر با debounce + Worker
  useEffect(() => {
    setIsProcessing(true);

    const timer = setTimeout(() => {
      workerRef.current?.postMessage({
        type: 'FILTER',
        payload: { items: initialItems, query: deferredQuery, filters: {} },
      });
    }, 150); // Debounce ۱۵۰ms

    return () => clearTimeout(timer);
  }, [deferredQuery, initialItems]);

  return { filteredItems, isProcessing, query, setQuery };
}

// ۳. کامپوننت اصلی با Virtualization
function MassiveDragDropList({ items }: { items: Item[] }) {
  const {
    filteredItems,
    isProcessing,
    query,
    setQuery,
  } = useMassiveList(items);

  const [order, setOrder] = useState<number[]>([]);

  // Syncing order با filteredItems
  useEffect(() => {
    setOrder(filteredItems.map((_, i) => i));
  }, [filteredItems]);

  // Drag & Drop Handler با اولویت بالا
  const handleDragEnd = useCallback((result: DropResult) => {
    if (!result.destination) return;

    // استفاده از startTransition برای آپدیت غیرفوری
    startTransition(() => {
      const newOrder = Array.from(order);
      const [removed] = newOrder.splice(result.source.index, 1);
      newOrder.splice(result.destination!.index, 0, removed);
      setOrder(newOrder);
    });

    // ارسال به Worker برای آپدیت داده اصلی
    workerRef.current?.postMessage({
      type: 'MOVE',
      payload: {
        fromIndex: result.source.index,
        toIndex: result.destination.index,
        items: filteredItems,
      },
    });
  }, [order, filteredItems]);

  return (
    <div>
      <SearchInput
        value={query}
        onChange={setQuery}
        isProcessing={isProcessing}
      />

      <DragDropContext onDragEnd={handleDragEnd}>
        <Droppable droppableId="list">
          {(provided) => (
            <div ref={provided.innerRef} {...provided.droppableProps}>
              <FixedSizeList
                height={600}
                width="100%"
                itemCount={filteredItems.length}
                itemSize={60}
                overscanCount={10} // بافر برای Drag & Drop
              >
                {({ index, style }) => (
                  <DraggableItem
                    key={filteredItems[index].id}
                    item={filteredItems[index]}
                    index={index}
                    style={style}
                  />
                )}
              </FixedSizeList>
              {provided.placeholder}
            </div>
          )}
        </Droppable>
      </DragDropContext>
    </div>
  );
}

// ۴. آیتم بهینه‌شده
const DraggableItem = React.memo(function DraggableItem({
  item,
  index,
  style,
}: {
  item: Item;
  index: number;
  style: React.CSSProperties;
}) {
  return (
    <Draggable draggableId={item.id} index={index}>
      {(provided, snapshot) => (
        <div
          ref={provided.innerRef}
          {...provided.draggableProps}
          {...provided.dragHandleProps}
          style={{
            ...style,
            ...provided.draggableProps.style,
            opacity: snapshot.isDragging ? 0.8 : 1,
            // GPU Acceleration
            transform: 'translate3d(0,0,0)',
          }}
        >
          <ItemContent item={item} />
        </div>
      )}
    </Draggable>
  );
}, (prev, next) => prev.item.id === next.item.id && prev.index === next.index);
```

