// ذخیره وضعیت مرتب‌سازی در IndexedDB
async function persistOrder(items: Item[]) {
  const db = await openDB('list-db', 1);
  const tx = db.transaction('items', 'readwrite');

  // نوشتن batch (سریع)
  for (const item of items) {
    tx.store.put(item);
  }

  await tx.done;
}

// ذخیره با Debounce (نه در هر Drag!)
const debouncedPersist = useMemo(
  () => debounce(persistOrder, 2000),
  []
);
```

