#### استراتژی حافظه:

```tsx
// ۱۰۰,۰۰۰ آیتم در حافظه = ~۵۰-۱۰۰MB
// راه‌حل: Windowed Data Loading

function useWindowedData(totalItems: number) {
  const [window, setWindow] = useState({ start: 0, end: 1000 });

  // فقط ۱۰۰۰ آیتم در حافظه، نه ۱۰۰,۰۰۰
  const visibleItems = useMemo(
    () => allItems.slice(window.start, window.end),
    [window]
  );

  // با اسکرول، window جابه‌جا می‌شود
  const handleScroll = useCallback((scrollOffset: number) => {
    const newStart = Math.floor(scrollOffset / ITEM_SIZE) - BUFFER;
    const newEnd = newStart + VISIBLE_COUNT + BUFFER * 2;
    setWindow({ start: Math.max(0, newStart), end: Math.min(totalItems, newEnd) });
  }, []);

  return { visibleItems, handleScroll };
}
```

