#### مشکل واقعی در React 17:

```tsx
// سناریوی واقعی: Autocomplete
function SearchComponent() {
  const [query, setQuery] = useState('');
  const [results, setResults] = useState([]);
  const [loading, setLoading] = useState(false);

  async function handleSearch(value: string) {
    setQuery(value);
    setLoading(true);  // ❌ React 17: رندر ۱ با loading=true, results=[]

    const data = await fetchResults(value);

    setResults(data);
    setLoading(false); // ❌ React 17: رندر ۲ با loading=false, results=data

    // مشکل: کاربر لحظه‌ای state ناسازگار می‌بیند
    // - loading=true اما results هنوز خالی است
    // - loading=false با results جدید (جهش ناگهانی)
    // - بین این دو رندر، UI ممکن است Flicker کند
  }

  return (
    <div>
      <Input value={query} onChange={handleSearch} />
      {loading && <Spinner />}
      <ResultsList results={results} />
    </div>
  );
}

// React 18:
// همه setها در یک رندر جمع می‌شوند:
// رندر نهایی: { query: newValue, loading: false, results: newData }
// بدون state میانی ناسازگار ✅
```

