#### چطور Automatic Batching کار می‌کند:

```typescript
// مفهوم ساده‌شده از پیاده‌سازی React 18

// React 18 از Scheduler برای زمان‌بندی رندر استفاده می‌کند
function dispatchSetState(component, newState) {
  // آپدیت را در صف قرار بده
  updateQueue.push({ component, newState });

  // به جای رندر فوری، یک میکروتسک زمان‌بندی کن
  scheduleMicrotask(() => {
    // همه آپدیت‌های جمع شده را یکجا پردازش کن
    const allUpdates = flushUpdateQueue();

    // یک رندر با همه آپدیت‌ها
    renderWithUpdates(allUpdates);
  });
}

// این یعنی:
setCount(1);  // به صف اضافه می‌شود
setFlag(true); // به صف اضافه می‌شود
// ... async operations ...
// میکروتسک اجرا می‌شود:
// رندر با count=1 و flag=true ✅
```

---

#### جدول مقایسه React 17 vs React 18:

| محل فراخوانی setState | React 17 | React 18 |
|------------------------|----------|----------|
| Event Handler (onClick) | ✅ Batched | ✅ Batched |
| setTimeout/setInterval | ❌ No Batch | ✅ Batched |
| Promise.then/catch | ❌ No Batch | ✅ Batched |
| async/await | ❌ No Batch | ✅ Batched |
| fetch callback | ❌ No Batch | ✅ Batched |
| Native event listener | ❌ No Batch | ✅ Batched |
| useEffect cleanup | ❌ No Batch | ✅ Batched |

---

#### نکته مهم: Automatic Batching فقط در createRoot:

```tsx
// React 17:
ReactDOM.render(<App />, document.getElementById('root'));
// Batching فقط در event handlerهای React

// React 18:
const root = createRoot(document.getElementById('root'));
root.render(<App />);
// Automatic Batching در همه جا ✅
```

> **خلاصه:** در React 18، دیگر لازم نیست نگران Batching باشید. هر جا state را آپدیت کنید، React به‌طور خودکار آنها را در یک رندر جمع می‌کند. این یعنی Performance بهتر و state همیشه سازگار.

### flushSync در React 18

**تعریف:**
`flushSync` یک escape hatch است که React را مجبور می‌کند آپدیت‌های درون callback را **بلافاصله و همزمان** رندر و commit کند، بدون اینکه آنها را با آپدیت‌های دیگر batch کند.

```tsx
import { flushSync } from 'react-dom';

flushSync(() => {
  setState(newValue); // بلافاصله رندر و commit می‌شود
});
// بعد از این خط، DOM قطعاً آپدیت شده
```

---

#### چه زمانی به flushSync نیاز داریم:

##### ۱. خواندن DOM بلافاصله بعد از state change:

```tsx
function ScrollToBottom() {
  const [messages, setMessages] = useState([]);
  const listRef = useRef<HTMLDivElement>(null);

  function addMessage(text: string) {
    // ❌ بدون flushSync: scrollHeight هنوز قدیمی است
    setMessages(prev => [...prev, { id: Date.now(), text }]);
    listRef.current?.scrollTo({
      top: listRef.current.scrollHeight, // این scrollHeight قدیمی است!
      behavior: 'smooth',
    });
    // مشکل: DOM هنوز آپدیت نشده → scrollHeight آپدیت نشده

    // ✅ با flushSync: DOM بلافاصله آپدیت می‌شود
    flushSync(() => {
      setMessages(prev => [...prev, { id: Date.now(), text }]);
    });
    // حالا DOM آپدیت شده و scrollHeight درست است
    listRef.current?.scrollTo({
      top: listRef.current.scrollHeight,
      behavior: 'smooth',
    });
  }

  return (
    <div>
      <div ref={listRef} className="messages">
        {messages.map(m => <Message key={m.id} text={m.text} />)}
      </div>
      <Input onSend={addMessage} />
    </div>
  );
}
```

##### ۲. هماهنگ‌سازی با کتابخانه‌های غیر React:

```tsx
function ChartComponent() {
  const [data, setData] = useState<DataPoint[]>([]);
  const chartRef = useRef<Chart | null>(null);

  function updateChart(newData: DataPoint[]) {
    // ❌ بدون flushSync: chart با DOM قدیمی آپدیت می‌شود
    setData(newData);
    chartRef.current?.update(); // ممکن است DOM قدیمی را ببیند

    // ✅ با flushSync: ابتدا DOM آپدیت شود، بعد chart
    flushSync(() => {
      setData(newData);
    });
    // حالا DOM قطعاً آپدیت شده
    chartRef.current?.update(); // DOM جدید را می‌بیند ✅
  }

  return (
    <div>
      <div ref={containerRef}>
        {/* chart.js داخل این div رندر می‌شود */}
      </div>
      <button onClick={() => updateChart(generateData())}>
        بروزرسانی
      </button>
    </div>
  );
}
```

