#### قوانین و نکات مهم:

| نکته | توضیح |
|------|-------|
| **فایل `.d.ts`** | حتماً در فایل declaration باشد |
| **Module vs Global** | `declare module` برای packageها، `declare global` برای window/DOM |
| **tsconfig include** | مطمئن شوید فایل‌های `.d.ts` در tsconfig include شده‌اند |
| **عدم export/import اضافی** | اگر `import/export` داشته باشید، فایل module می‌شود، نه ambient |
| **استفاده با احتیاط** | Declaration Merging را برای رفع مشکلات واقعی استفاده کنید |

```json
// tsconfig.json
{
  "compilerOptions": {
    "typeRoots": ["./node_modules/@types", "./types"]
  },
  "include": [
    "src/**/*",
    "types/**/*.d.ts"  // ← فولدر types را include کنید
  ]
}
```

> **خلاصه:** Declaration Merging یک ابزار قدرتمند برای گسترش تایپ‌های کتابخانه‌های third-party بدون fork کردن آنهاست. از آن برای اضافه کردن props سفارشی، متادیتا، یا theme استفاده کنید. همیشه در فایل‌های `.d.ts` و با `declare module` یا `declare global` انجام دهید.

### ComponentPropsWithoutRef در مقابل ComponentPropsWithRef

---

#### تعریف:

```typescript
// TypeScript داخلی React:

// ComponentPropsWithoutRef: تمام props یک المان به جز ref
type ComponentPropsWithoutRef<T extends ElementType> = {
  // تمام props استاندارد HTML المان
  // بدون ref
};

// ComponentPropsWithRef: تمام props یک المان با ref
type ComponentPropsWithRef<T extends ElementType> = {
  // تمام props استاندارد HTML المان
  // شامل ref
};
```

---

#### مثال پایه:

```tsx
import { ComponentPropsWithoutRef, ComponentPropsWithRef, forwardRef } from 'react';

// ۱. ComponentPropsWithoutRef: برای کامپوننت‌های بدون forwardRef
interface ButtonProps extends ComponentPropsWithoutRef<'button'> {
  variant?: 'primary' | 'secondary';
  loading?: boolean;
}

function Button({ variant, loading, children, ...restProps }: ButtonProps) {
  return (
    <button className={`btn btn-${variant}`} {...restProps}>
      {loading && <Spinner />}
      {children}
    </button>
  );
}

// استفاده:
<Button variant="primary" onClick={handleClick}>
  کلیک
</Button>
// ref={...} ❌ خطا: ButtonProps شامل ref نیست


// ۲. ComponentPropsWithRef: برای کامپوننت‌های با forwardRef
interface ButtonWithRefProps extends ComponentPropsWithRef<'button'> {
  variant?: 'primary' | 'secondary';
  loading?: boolean;
}

const ButtonWithRef = forwardRef<HTMLButtonElement, ButtonWithRefProps>(
  ({ variant, loading, children, ...restProps }, ref) => {
    return (
      <button ref={ref} className={`btn btn-${variant}`} {...restProps}>
        {loading && <Spinner />}
        {children}
      </button>
    );
  }
);

// استفاده:
const buttonRef = useRef<HTMLButtonElement>(null);
<ButtonWithRef ref={buttonRef} variant="primary">
  کلیک
</ButtonWithRef>
// ref={...} ✅
```

---

#### تفاوت‌های کلیدی:

| ویژگی | WithoutRef | WithRef |
|--------|------------|---------|
| **شامل ref** | ❌ | ✅ |
| **استفاده با forwardRef** | نیاز به تایپ دستی ref | ✅ مستقیم |
| **استفاده در کامپوننت ساده** | ✅ | ⚠️ ref اضافی |
| **وقتی ref را پاس نمی‌دهید** | ✅ امن‌تر | ⚠️ امکان پاس ref |

---

#### سناریوهای واقعی:

##### ۱. کامپوننت بدون forwardRef (اکثر مواقع):

```tsx
// ✅ استفاده از WithoutRef
interface CardProps extends ComponentPropsWithoutRef<'div'> {
  title: string;
  elevation?: 0 | 1 | 2 | 3;
}

function Card({ title, elevation = 1, children, ...restProps }: CardProps) {
  return (
    <div
      className={`card elevation-${elevation}`}
      {...restProps}
    >
      <h2>{title}</h2>
      {children}
    </div>
  );
}

// استفاده:
<Card
  title="محصول ویژه"
  onClick={handleClick}
  aria-label="کارت محصول"
>
  <p>توضیحات</p>
</Card>
```

##### ۲. کامپوننت با forwardRef (ضروری):

```tsx
// ✅ استفاده از WithRef
interface InputProps extends ComponentPropsWithRef<'input'> {
  label: string;
  error?: string;
}

const Input = forwardRef<HTMLInputElement, InputProps>(
  ({ label, error, className, ...restProps }, ref) => {
    return (
      <div className="form-field">
        <label>{label}</label>
        <input
          ref={ref}
          className={`input ${error ? 'input--error' : ''} ${className}`}
          aria-invalid={!!error}
          {...restProps}
        />
        {error && <span className="error">{error}</span>}
      </div>
    );
  }
);

// استفاده با ref:
function Form() {
  const inputRef = useRef<HTMLInputElement>(null);

  function focusInput() {
    inputRef.current?.focus();
  }

  return (
    <>
      <Input
        ref={inputRef}
        label="ایمیل"
        type="email"
        placeholder="example@email.com"
      />
      <button onClick={focusInput}>فوکوس روی ایمیل</button>
    </>
  );
}
```

##### ۳. استخراج تایپ برای Polymorphic Components:

```tsx
// زمانی که کامپوننت می‌تواند المان‌های مختلف باشد:
import { ComponentPropsWithoutRef, ElementType } from 'react';

type PolymorphicProps<T extends ElementType = 'div'> = {
  as?: T;
} & ComponentPropsWithoutRef<T>;

function Box<T extends ElementType = 'div'>({
  as,
  ...restProps
}: PolymorphicProps<T>) {
  const Component = as || 'div';
  return <Component {...restProps} />;
}

// استفاده:
<Box as="button" onClick={handleClick} type="button">
  کلیک
</Box>
// onClick و type فقط برای button معتبرند ✅
<Box as="a" href="/home" target="_blank">
  لینک
</Box>
// href و target فقط برای a معتبرند ✅
```

---

#### چه زمانی از کدام استفاده کنیم:

```tsx
// ✅ WithoutRef: کامپوننت ساده، بدون نیاز به ref از والد
interface SimpleComponentProps extends ComponentPropsWithoutRef<'div'> {}

// ✅ WithoutRef + forwardRef سفارشی:
// وقتی می‌خواهید ref را expose کنید اما کنترل بیشتری داشته باشید
interface ControlledComponentProps extends ComponentPropsWithoutRef<'input'> {
  // ref به صورت دستی تایپ می‌شود
}

const ControlledComponent = forwardRef<HTMLInputElement, ControlledComponentProps>(
  (props, ref) => <input ref={ref} {...props} />
);

// ✅ WithRef: وقتی forwardRef دارید و می‌خواهید تایپ ref خودکار باشد
interface AutoRefComponentProps extends ComponentPropsWithRef<'input'> {}

const AutoRefComponent = forwardRef<HTMLInputElement, AutoRefComponentProps>(
  (props, ref) => <input ref={ref} {...props} />
);

// ⚠️ WithRef بدون forwardRef (نادر):
// ممکن است کاربر ref پاس دهد اما کامپوننت از آن استفاده نکند
interface PropsWithUnusedRef extends ComponentPropsWithRef<'div'> {}

function NoRefComponent({ ...props }: PropsWithUnusedRef) {
  return <div {...props} />;
  // props شامل ref می‌شود اما استفاده نمی‌شود
  // React 19 warning: ref prop on component without forwardRef
}
```

---

#### جدول تصمیم‌گیری:

| سناریو | استفاده کنید |
|--------|-------------|
| کامپوننت ساده بدون ref | `ComponentPropsWithoutRef` |
| کامپوننت با `forwardRef` | `ComponentPropsWithRef` یا `WithoutRef` + تایپ دستی ref |
| Polymorphic Component | `ComponentPropsWithoutRef<T>` |
| کامپوننت UI Kit که باید ref بپذیرد | `ComponentPropsWithRef` + `forwardRef` |
| نمی‌خواهید کسی ref پاس دهد | `ComponentPropsWithoutRef` (امن‌تر) |

> **قانون طلایی:** `WithoutRef` پیش‌فرض امن‌تر است. فقط وقتی `WithRef` استفاده کنید که واقعاً `forwardRef` دارید و می‌خواهید ref از والد دریافت کنید.

### استفاده از `never` در Discriminated Union

`never` در Discriminated Union به TypeScript می‌گوید که یک prop **هرگز نباید** در یک variant خاص وجود داشته باشد. این کار ترکیب‌های نامعتبر را در زمان کامپایل غیرممکن می‌کند.

---

#### ❌ مشکل: Props اختیاری که می‌توانند ناسازگار باشند:

```tsx
// مشکل: می‌توان ترکیب‌های نامعتبر ساخت
interface ButtonProps {
  variant: 'primary' | 'secondary' | 'link';

  // Props مربوط به link
  href?: string;
  target?: '_blank' | '_self';

  // Props مربوط به button
  onClick?: () => void;
  type?: 'button' | 'submit' | 'reset';
  disabled?: boolean;

  // Props مربوط به primary
  size?: 'sm' | 'md' | 'lg';

  // Props مربوط به secondary  
  outline?: boolean;
}

// مشکلات:
// ۱. می‌توان variant="link" و type="submit" را همزمان داشت (نامعتبر)
// ۲. می‌توان variant="primary" و href="/home" را همزمان داشت (نامعتبر)
// ۳. TypeScript هیچ کمکی نمی‌کند

<Button variant="link" type="submit">کلیک</Button> // ❌ منطقاً نامعتبر، اما TypeScript قبول می‌کند
<Button variant="primary" href="/home">کلیک</Button> // ❌ نامعتبر
```

---

#### ✅ راه‌حل: Discriminated Union با `never`:

```tsx
// ۱. تعریف variantهای مجزا با never
type ButtonProps =
  | {
      variant: 'primary' | 'secondary';
      href?: never;        // ❌ هرگز نباید href داشته باشد
      target?: never;      // ❌ هرگز نباید target داشته باشد

      onClick?: () => void;
      type?: 'button' | 'submit' | 'reset';
      disabled?: boolean;
      size?: 'sm' | 'md' | 'lg';
      outline?: boolean;
    }
  | {
      variant: 'link';
      href: string;        // ✅ حتماً باید href داشته باشد
      target?: '_blank' | '_self';

      onClick?: never;     // ❌ نباید onClick داشته باشد (از href استفاده کن)
      type?: never;        // ❌ نباید type داشته باشد
      disabled?: never;    // ❌ نباید disabled داشته باشد
      size?: never;        // ❌ نباید size داشته باشد
      outline?: never;     // ❌ نباید outline داشته باشد
    };

function Button(props: ButtonProps) {
  if (props.variant === 'link') {
    return (
      <a href={props.href} target={props.target}>
        {props.children}
      </a>
    );
  }

  return (
    <button
      onClick={props.onClick}
      type={props.type}
      disabled={props.disabled}
      className={`btn btn-${props.variant} size-${props.size}`}
    >
      {props.children}
    </button>
  );
}

// ✅ استفاده درست:
<Button variant="primary" size="lg" onClick={handleClick}>
  کلیک
</Button>

<Button variant="link" href="/home" target="_blank">
  صفحه اصلی
</Button>

// ❌ خطاهای TypeScript:
<Button variant="primary" href="/home">خطا</Button>
// Type error: 'href' does not exist in type 'primary' variant

<Button variant="link" onClick={handleClick}>خطا</Button>
// Type error: 'onClick' does not exist in type 'link' variant

<Button variant="link" type="submit">خطا</Button>
// Type error: 'type' does not exist in type 'link' variant
```

---

#### مثال پیشرفته‌تر: Modal با حالت‌های مختلف:

```tsx
type ModalProps =
  | {
      mode: 'confirm';
      title: string;
      message: string;
      onConfirm: () => void;
      onCancel: () => void;

      // این props هرگز در confirm وجود ندارند
      onSubmit?: never;
      children?: never;
      formFields?: never;
    }
  | {
      mode: 'form';
      title: string;
      onSubmit: (data: FormData) => void;
      onCancel: () => void;
      children: React.ReactNode; // فرم داخل children
      formFields?: FormField[];

      // این props هرگز در form وجود ندارند
      message?: never;
      onConfirm?: never;
    }
  | {
      mode: 'custom';
      children: React.ReactNode;
      onClose?: () => void;

      // این props هرگز در custom وجود ندارند
      title?: never;
      message?: never;
      onConfirm?: never;
      onCancel?: never;
      onSubmit?: never;
      formFields?: never;
    };

function Modal(props: ModalProps) {
  switch (props.mode) {
    case 'confirm':
      return (
        <div className="modal">
          <h2>{props.title}</h2>
          <p>{props.message}</p>
          <button onClick={props.onConfirm}>تأیید</button>
          <button onClick={props.onCancel}>انصراف</button>
        </div>
      );

    case 'form':
      return (
        <div className="modal">
          <h2>{props.title}</h2>
          <form onSubmit={props.onSubmit}>
            {props.children}
            <button type="submit">ارسال</button>
            <button type="button" onClick={props.onCancel}>انصراف</button>
          </form>
        </div>
      );

    case 'custom':
      return (
        <div className="modal">
          {props.children}
          {props.onClose && <button onClick={props.onClose}>بستن</button>}
        </div>
      );
  }
}

// ✅ استفاده:
<Modal
  mode="confirm"
  title="حذف"
  message="آیا مطمئن هستید؟"
  onConfirm={handleDelete}
  onCancel={handleClose}
/>

<Modal
  mode="form"
  title="ثبت نام"
  onSubmit={handleSubmit}
  onCancel={handleClose}
>
  <Input name="email" />
  <Input name="password" />
</Modal>

// ❌ خطا:
<Modal mode="confirm" onSubmit={...} />
// 'onSubmit' does not exist
```

