#### `never` در مقابل `optional`:

```tsx
// ❌ optional: هنوز می‌توان پاس داد (undefined یا مقدار)
interface BadProps {
  variant: 'primary' | 'link';
  href?: string;    // می‌توان href پاس داد حتی برای primary
  onClick?: () => void; // می‌توان onClick پاس داد حتی برای link
}

<BadProps variant="primary" href="/home" /> // ❌ قبول می‌کند!

// ✅ never: اصلاً نمی‌توان پاس داد
interface GoodProps =
  | { variant: 'primary'; href?: never; onClick?: () => void }
  | { variant: 'link'; href: string; onClick?: never }

<GoodProps variant="primary" href="/home" /> // ❌ خطای TypeScript!
// Type 'string' is not assignable to type 'undefined'
```

