#### تکنیک پیشرفته: نوع کمکی برای never:

```typescript
// اگر تعداد variantها زیاد است، می‌توان از نوع کمکی استفاده کرد
type StrictVariant<Variants extends Record<string, Record<string, unknown>>> = {
  [K in keyof Variants]: {
    variant: K;
  } & {
    [P in keyof Variants[K]]: Variants[K][P];
  } & {
    // همه propهای دیگر را never کن
    [P in Exclude<AllProps, keyof Variants[K] | 'variant'>]?: never;
  };
}[keyof Variants];

// استفاده:
type ButtonVariants = {
  primary: { size?: 'sm' | 'md' | 'lg'; onClick?: () => void };
  link: { href: string; target?: '_blank' | '_self' };
  icon: { icon: React.ReactNode; label: string; onClick?: () => void };
};

type ButtonProps = StrictVariant<ButtonVariants>;
```

---

#### مزایای استفاده از `never`:

| مزیت | توضیح |
|-------|-------|
| **Type Safety کامل** | ترکیب‌های نامعتبر در زمان کامپایل خطا می‌دهند |
| **Autocomplete بهتر** | TypeScript فقط props مرتبط با variant فعلی را نشان می‌دهد |
| **Self-documenting** | با دیدن تایپ، می‌فهمید هر variant چه propsی دارد |
| **Refactoring امن** | تغییر تایپ یک variant روی بقیه تأثیر نمی‌گذارد |
| **Exhaustive Check** | TypeScript اطمینان می‌دهد همه variantها هندل شده‌اند |

> **قانون:** هر جا چند variant با props متفاوت دارید، از Discriminated Union با `never` استفاده کنید. `never` یعنی "این prop در این حالت وجود خارجی ندارد" و TypeScript را مجبور به بررسی دقیق‌تر می‌کند.

### Polymorphic Component با TypeScript کامل

**هدف:** کامپوننتی که با `as` prop می‌تواند المان‌های مختلف باشد و TypeScript props صحیح هر المان را تشخیص دهد.

---

#### نسخه ۱: پایه (بدون ref):

```tsx
import { ComponentPropsWithoutRef, ElementType, ReactNode } from 'react';

// ۱. تایپ پایه Polymorphic
type PolymorphicProps<T extends ElementType = 'div'> = {
  as?: T;
  children?: ReactNode;
} & ComponentPropsWithoutRef<T>;

// ۲. کامپوننت
function Box<T extends ElementType = 'div'>({
  as,
  children,
  ...restProps
}: PolymorphicProps<T>) {
  const Component = as || 'div';
  return <Component {...restProps}>{children}</Component>;
}

// ۳. استفاده:
<Box>Default div</Box>
<Box as="button" onClick={() => {}} type="button">Button</Box>
<Box as="a" href="/home" target="_blank">Link</Box>
<Box as="section" aria-label="Products">Section</Box>

// TypeScript بررسی می‌کند:
// ❌ <Box as="a" type="submit"> // Error: 'type' not valid for 'a'
// ❌ <Box as="button" href="/home"> // Error: 'href' not valid for 'button'
```

---

#### نسخه ۲: با forwardRef (کامل):

```tsx
import { forwardRef, ElementType, ComponentPropsWithoutRef, ComponentPropsWithRef } from 'react';

// ۱. تایپ‌های کمکی
type PolymorphicRef<T extends ElementType> = ComponentPropsWithRef<T>['ref'];

type PolymorphicProps<
  T extends ElementType = 'div',
  TProps = {}
> = {
  as?: T;
  children?: ReactNode;
} & TProps &
  Omit<ComponentPropsWithoutRef<T>, keyof TProps | 'as'>;

// ۲. کامپوننت با forwardRef
type BoxComponent = <T extends ElementType = 'div'>(
  props: PolymorphicProps<T> & { ref?: PolymorphicRef<T> }
) => JSX.Element | null;

const Box = forwardRef(function Box<T extends ElementType = 'div'>(
  { as, children, ...restProps }: PolymorphicProps<T>,
  ref: PolymorphicRef<T>
) {
  const Component = as || 'div';

  return (
    <Component ref={ref} {...restProps}>
      {children}
    </Component>
  );
}) as BoxComponent;

// ۳. استفاده با ref:
function Example() {
  const linkRef = useRef<HTMLAnchorElement>(null);
  const buttonRef = useRef<HTMLButtonElement>(null);

  return (
    <>
      <Box as="a" ref={linkRef} href="/home">
        لینک با ref
      </Box>
      {/* TypeScript می‌داند ref از نوع HTMLAnchorElement است ✅ */}

      <Box as="button" ref={buttonRef} onClick={() => {}}>
        دکمه با ref
      </Box>
      {/* TypeScript می‌داند ref از نوع HTMLButtonElement است ✅ */}
    </>
  );
}
```

---

#### نسخه ۳: با Props سفارشی (Design System):

```tsx
// ۱. Props اختصاصی کامپوننت
interface BoxOwnProps {
  padding?: 'none' | 'sm' | 'md' | 'lg';
  margin?: 'none' | 'sm' | 'md' | 'lg';
  backgroundColor?: string;
  display?: 'block' | 'flex' | 'grid' | 'inline';
  flexDirection?: 'row' | 'column';
  gap?: number;
  alignItems?: 'start' | 'center' | 'end' | 'stretch';
  justifyContent?: 'start' | 'center' | 'end' | 'between' | 'around';
}

// ۲. تایپ Polymorphic با OwnProps
type PolymorphicBoxProps<T extends ElementType = 'div'> = PolymorphicProps<
  T,
  BoxOwnProps
>;

// ۳. کامپوننت
const Box = forwardRef(function Box<T extends ElementType = 'div'>(
  {
    as,
    children,
    padding = 'none',
    margin = 'none',
    backgroundColor,
    display,
    flexDirection,
    gap,
    alignItems,
    justifyContent,
    style,
    ...restProps
  }: PolymorphicBoxProps<T>,
  ref: PolymorphicRef<T>
) {
  const Component = as || 'div';

  const computedStyle = {
    padding: paddingMap[padding],
    margin: paddingMap[margin],
    backgroundColor,
    display,
    flexDirection,
    gap: gap ? `${gap * 4}px` : undefined,
    alignItems,
    justifyContent,
    ...style,
  };

  return (
    <Component ref={ref} style={computedStyle} {...restProps}>
      {children}
    </Component>
  );
}) as <T extends ElementType = 'div'>(
  props: PolymorphicBoxProps<T> & { ref?: PolymorphicRef<T> }
) => JSX.Element;

// ۴. استفاده:
<Box
  as="section"
  padding="lg"
  display="flex"
  gap={4}
  alignItems="center"
  aria-label="Products"
>
  <h2>محصولات</h2>
</Box>

// OwnProps + HTML props هر دو معتبرند ✅
// TypeScript هر دو را چک می‌کند
```

---

#### نسخه ۴: با محدودیت در as (فقط تگ‌های خاص):

```tsx
// محدود کردن as به تگ‌های خاص
type AllowedElements = 'div' | 'section' | 'article' | 'main' | 'aside' | 'nav';

function Container<T extends AllowedElements = 'div'>(
  props: PolymorphicProps<T>
) {
  const Component = props.as || 'div';
  return <Component {...props} />;
}

// ✅ فقط این تگ‌ها:
<Container as="section" />
<Container as="article" />
<Container as="nav" />

// ❌ خطا:
<Container as="button" /> // Type error: not assignable
<Container as="span" />   // Type error: not assignable
```

---

#### تایپ‌های کمکی پیشرفته:

```typescript
// ۱. استخراج ref type از ElementType
type PolymorphicRef<T extends ElementType> = 
  T extends keyof JSX.IntrinsicElements
    ? JSX.IntrinsicElements[T]['ref']
    : ComponentPropsWithRef<T>['ref'];

// ۲. تایپ برای کامپوننت‌های Custom به عنوان as
type CustomComponent = (props: { specialProp: boolean }) => JSX.Element;

<Box as={CustomComponent} specialProp={true} />
// TypeScript باید props مربوط به CustomComponent را بشناسد

// ۳. تایپ کامل برای پشتیبانی از هر دو (Intrinsic + Custom)
type ExtendedPolymorphicProps<T extends ElementType> = {
  as?: T;
} & Omit<
  T extends keyof JSX.IntrinsicElements
    ? ComponentPropsWithoutRef<T>
    : ComponentPropsWithoutRef<T>,
  'as'
>;
```

---

#### نکات کلیدی:

| نکته | توضیح |
|------|-------|
| **Generic پیش‌فرض** | `<T extends ElementType = 'div'>` - div پیش‌فرض |
| **Omit برای as** | `Omit<..., 'as'>` تا as دو بار تعریف نشود |
| **Ref با forwardRef** | حتماً از `forwardRef` برای پشتیبانی ref استفاده کنید |
| **Type Assertion** | برای تایپ صحیح ref در forwardRef نیاز به `as` است |
| **OwnProps جدا** | Props اختصاصی را در اینترفیس جداگانه تعریف کنید |

```typescript
// الگوی نهایی (کپی-پیست آماده):
import { forwardRef, ElementType, ComponentPropsWithoutRef, ComponentPropsWithRef } from 'react';

type PolymorphicRef<T extends ElementType> = ComponentPropsWithRef<T>['ref'];

type PolymorphicProps<T extends ElementType = 'div', TProps = {}> = {
  as?: T;
} & TProps &
  Omit<ComponentPropsWithoutRef<T>, keyof TProps | 'as'>;

type PolymorphicComponent = <T extends ElementType = 'div'>(
  props: PolymorphicProps<T> & { ref?: PolymorphicRef<T> }
) => JSX.Element | null;
```

> **خلاصه:** Polymorphic Component با TypeScript کامل نیاز به Generic `T extends ElementType`، `Omit` برای جلوگیری از تداخل props، و `forwardRef` با type assertion دارد. نتیجه: یک API انعطاف‌پذیر با type safety کامل.

### `infer` در TypeScript

**تعریف:**
`infer` کلمه‌ای کلیدی است که به TypeScript اجازه می‌دهد **تایپ را از یک ساختار استخراج کند** (Type Inference درون Conditional Types).

---

#### ۱. استخراج تایپ از Promise:

```typescript
// ❌ بدون infer: باید دستی تایپ کنی
const response = await fetch('/api/users');
const data: User[] = await response.json();

// ✅ با infer: تایپ خودکار استخراج می‌شود
type Awaited<T> = T extends Promise<infer U> ? U : T;

// استفاده:
type UserPromise = Promise<User[]>;
type Users = Awaited<UserPromise>; // User[]

type NotPromise = string;
type StillString = Awaited<NotPromise>; // string

// نسخه بازگشتی (Promise تودرتو):
type DeepAwaited<T> = T extends Promise<infer U>
  ? DeepAwaited<U>
  : T;

type Nested = Promise<Promise<Promise<number>>>;
type Flat = DeepAwaited<Nested>; // number
```

---

#### ۲. استخراج Props از کامپوننت React:

```typescript
import { ComponentProps } from 'react';

// کامپوننت نمونه
function Button({ 
  variant, 
  size, 
  children 
}: { 
  variant: 'primary' | 'secondary';
  size?: 'sm' | 'md' | 'lg';
  children: React.ReactNode;
}) {
  return <button className={`btn-${variant} btn-${size}`}>{children}</button>;
}

// ✅ استخراج خودکار Props:
type ButtonProps = ComponentProps<typeof Button>;
// {
//   variant: 'primary' | 'secondary';
//   size?: 'sm' | 'md' | 'lg';
//   children: React.ReactNode;
// }

// حالا می‌توانید از این تایپ استفاده کنید:
const buttonConfig: ButtonProps = {
  variant: 'primary',
  size: 'lg',
  children: 'کلیک',
};
```

---

#### ۳. استخراج Return Type از تابع:

```typescript
// تابع custom hook
function useUser(userId: string) {
  const [user, setUser] = useState<User | null>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    fetchUser(userId).then(setUser).finally(() => setLoading(false));
  }, [userId]);

  return { user, loading, refetch: () => fetchUser(userId) };
}

// ✅ استخراج ReturnType:
type UseUserReturn = ReturnType<typeof useUser>;
// {
//   user: User | null;
//   loading: boolean;
//   refetch: () => Promise<User>;
// }

// استفاده در کامپوننت دیگر:
function UserProfile({ userId }: { userId: string }) {
  // تایپ از روی هوک اصلی:
  const { user, loading } = useUser(userId);
  // user: User | null ✅
  // loading: boolean ✅
}
```

