#### ۵. استخراج Function Parameters:

```typescript
// استخراج پارامترهای تابع
type FirstParam<T> = T extends (first: infer F, ...rest: any[]) => any
  ? F
  : never;

// استفاده:
function handleClick(event: React.MouseEvent, id: string) {
  console.log(id);
}

type EventType = FirstParam<typeof handleClick>; // React.MouseEvent
type IDType = FirstParam<typeof handleClick>; // فقط پارامتر اول

// استخراج همه پارامترها:
type AllParams<T> = T extends (...args: infer P) => any ? P : never;
type HandleClickParams = AllParams<typeof handleClick>;
// [React.MouseEvent, string]
```

