#### ۶. استخراج تایپ‌های پیچیده از API Response:

```typescript
// ساختار API Response معمولی
interface ApiResponse<T> {
  data: T;
  meta: {
    total: number;
    page: number;
  };
  error?: string;
}

// ✅ استخراج T از ApiResponse:
type ExtractData<T> = T extends ApiResponse<infer D> ? D : never;

// استفاده:
type UserResponse = ApiResponse<User[]>;
type Users = ExtractData<UserResponse>; // User[]

type ProductResponse = ApiResponse<Product>;
type Product = ExtractData<ProductResponse>; // Product

// استخراج چندگانه:
type ExtractApiTypes<T> = T extends ApiResponse<infer D>
  ? { data: D; meta: ApiResponse<D>['meta'] }
  : never;
```

