#### ۷. استفاده پیشرفته با React Query:

```typescript
import { useQuery, UseQueryResult } from '@tanstack/react-query';

// ✅ استخراج تایپ data از useQuery:
type QueryData<T> = T extends UseQueryResult<infer D> ? D : never;

// استفاده:
function useUsers() {
  return useQuery({
    queryKey: ['users'],
    queryFn: () => fetchUsers(),
  });
}

type UsersQueryResult = ReturnType<typeof useUsers>;
type Users = QueryData<UsersQueryResult>; // User[]

// حالا در کامپوننت دیگر:
function UserCount() {
  const { data } = useUsers();
  // data: User[] | undefined ✅
}
