#### ۹. پیاده‌سازی type-safe event emitter:

```typescript
// تعریف event map
type EventMap = {
  userLogin: { userId: string; timestamp: Date };
  userLogout: { userId: string };
  error: { message: string; code: number };
};

// ✅ استفاده از infer برای type-safe emit/on:
class TypedEmitter<T extends Record<string, unknown>> {
  private handlers = new Map<keyof T, Set<Function>>();

  on<K extends keyof T>(event: K, handler: (data: T[K]) => void) {
    // ...
  }

  emit<K extends keyof T>(event: K, data: T[K]) {
    // ...
  }
}

const emitter = new TypedEmitter<EventMap>();

emitter.on('userLogin', (data) => {
  // data: { userId: string; timestamp: Date } ✅
  console.log(data.userId, data.timestamp);
});

emitter.emit('userLogin', {
  userId: '123',
  timestamp: new Date(),
});

// ❌ خطا:
emitter.emit('userLogin', { userId: '123' }); // timestamp missing
emitter.emit('unknown', {}); // unknown not in EventMap
```

