#### ✅ تست مبتنی بر User Behavior:

تستی که به **نتیجه** و **رفتار قابل مشاهده توسط کاربر** اهمیت می‌دهد.

```tsx
// ✅ تست User Behavior:
import { render, screen } from '@testing-library/react';
import userEvent from '@testing-library/user-event';

test('Counter - User Behavior Test', () => {
  render(<Counter />);

  // ۱. پیدا کردن با نقش (role) - چیزی که کاربر می‌بیند
  const incrementButton = screen.getByRole('button', { name: /افزایش/i });
  const decrementButton = screen.getByRole('button', { name: /کاهش/i });

  // ۲. پیدا کردن heading - بدون data-testid
  const heading = screen.getByRole('heading');

  // ۳. بررسی مقدار اولیه (آنچه کاربر می‌بیند)
  expect(heading).toHaveTextContent('شمارش: 0');

  // ۴. تعامل مانند کاربر واقعی
  await userEvent.click(incrementButton);
  await userEvent.click(incrementButton);

  // ۵. بررسی نتیجه (آنچه کاربر می‌بیند)
  expect(heading).toHaveTextContent('شمارش: 2');

  // ۶. تعامل کاهش
  await userEvent.click(decrementButton);
  expect(heading).toHaveTextContent('شمارش: 1');
});

// ✅ بعد از Refactor، تست هنوز کار می‌کند:
function Counter() {
  // ... (همان refactor قبلی)
  return (
    <section aria-label="counter">
      <h2>شمارش: {count}</h2>
      <button aria-label="کاهش" onClick={decrement}>-</button>
      <button aria-label="افزایش" onClick={increment}>+</button>
    </section>
  );
}

// ✅ تست اصلاح شده (فقط queryها تغییر می‌کنند):
const incrementButton = screen.getByRole('button', { name: /افزایش/i });
// یا:
const incrementButton = screen.getByLabelText('افزایش');
```

