#### مثال واقعی‌تر: فرم جستجو:

```tsx
// کامپوننت جستجو
function SearchForm({ onSearch }: { onSearch: (query: string) => void }) {
  const [query, setQuery] = useState('');

  function handleSubmit(e: React.FormEvent) {
    e.preventDefault();
    onSearch(query);
  }

  return (
    <form onSubmit={handleSubmit}>
      <label htmlFor="search">جستجو</label>
      <input
        id="search"
        type="text"
        value={query}
        onChange={(e) => setQuery(e.target.value)}
      />
      <button type="submit">جستجو</button>
    </form>
  );
}

// ❌ تست Implementation Detail:
test('SearchForm - Implementation Detail', () => {
  const handleSearch = jest.fn();
  const { container } = render(<SearchForm onSearch={handleSearch} />);

  const input = container.querySelector('#search');
  const form = container.querySelector('form');

  // تست مستقیم state
  fireEvent.change(input!, { target: { value: 'React' } });
  expect(input?.value).toBe('React'); // تست value attribute

  fireEvent.submit(form!);
  expect(handleSearch).toHaveBeenCalledWith('React');

  // اگر input از controlled به uncontrolled تغییر کند:
  // - defaultValue به جای value
  // - تست input.value می‌شکند
  // اگر form با div عوض شود و onSubmit با onKeyDown:
  // - تست fireEvent.submit می‌شکند
});

// ✅ تست User Behavior:
test('SearchForm - User Behavior', async () => {
  const handleSearch = jest.fn();
  render(<SearchForm onSearch={handleSearch} />);

  // ۱. پیدا کردن input با label (کاری که کاربر می‌کند)
  const input = screen.getByLabelText(/جستجو/i);
  const button = screen.getByRole('button', { name: /جستجو/i });

  // ۲. تایپ مانند کاربر
  await userEvent.type(input, 'React');

  // ۳. کلیک مانند کاربر (نه submit مستقیم form)
  await userEvent.click(button);

  // ۴. بررسی callback
  expect(handleSearch).toHaveBeenCalledWith('React');

  // اگر input از controlled به uncontrolled تغییر کند → تست نمی‌شکند
  // اگر form حذف شود → تست فقط query button را عوض می‌کند
});
```

