##### لایه ۲: Unit Tests (منطق خالص):
```typescript
// ✅ Unit Test: توابع خالص، utilityها، custom hooks ساده
describe('calculateDiscount', () => {
  it('should apply 10% discount for premium users', () => {
    const result = calculateDiscount(100, 'premium');
    expect(result).toBe(90);
  });

  it('should not apply discount for regular users', () => {
    const result = calculateDiscount(100, 'regular');
    expect(result).toBe(100);
  });
});

// ✅ Unit Test: custom hook ساده
describe('useDebounce', () => {
  it('should debounce value changes', async () => {
    const { result, rerender } = renderHook(
      ({ value }) => useDebounce(value, 300),
      { initialProps: { value: 'test' } }
    );

    expect(result.current).toBe('test');

    rerender({ value: 'testing' });
    expect(result.current).toBe('test'); // هنوز تغییر نکرده

    await waitFor(() => {
      expect(result.current).toBe('testing');
    }, { timeout: 400 });
  });
});
```

##### لایه ۳: Integration Tests (بیشترین ارزش):
```typescript
// ✅ Integration Test: کامپوننت + تعاملات + API mock
describe('ProductSearch Integration', () => {
  it('should search and display products', async () => {
    // Mock API
    server.use(
      http.get('/api/products', () => {
        return HttpResponse.json([
          { id: 1, name: 'React Book', price: 29.99 },
        ]);
      })
    );

    render(<ProductSearch />);

    // کاربر تایپ می‌کند
    const input = screen.getByLabelText(/جستجوی محصول/i);
    await userEvent.type(input, 'React');

    // منتظر نتایج
    await screen.findByText('React Book');
    expect(screen.getByText('$29.99')).toBeVisible();

    // کاربر روی محصول کلیک می‌کند
    await userEvent.click(screen.getByText('React Book'));

    // به صفحه محصول رفته
    expect(screen.getByRole('heading')).toHaveTextContent('React Book');
  });

  it('should show empty state when no results', async () => {
    server.use(
      http.get('/api/products', () => {
        return HttpResponse.json([]);
      })
    );

    render(<ProductSearch />);

    await userEvent.type(
      screen.getByLabelText(/جستجوی محصول/i),
      'NonExistent'
    );

    await screen.findByText(/محصولی یافت نشد/i);
  });

  it('should handle network errors gracefully', async () => {
    server.use(
      http.get('/api/products', () => {
        return HttpResponse.error();
      })
    );

    render(<ProductSearch />);

    await userEvent.type(
      screen.getByLabelText(/جستجوی محصول/i),
      'Test'
    );

    await screen.findByText(/خطا در دریافت نتایج/i);
    expect(screen.getByRole('button', { name: /تلاش مجدد/i })).toBeVisible();
  });
});
```

##### لایه ۴: E2E Tests (Critical Paths):
```typescript
// ✅ E2E: فقط مسیرهای حیاتی کسب‌وکار
test('User can complete purchase flow', async ({ page }) => {
  // ۱. ورود
  await page.goto('/login');
  await page.fill('[aria-label="ایمیل"]', 'user@example.com');
  await page.fill('[aria-label="رمز عبور"]', 'password');
  await page.click('button:has-text("ورود")');

  // ۲. جستجوی محصول
  await page.fill('[aria-label="جستجو"]', 'React Book');
  await page.click('text=React Book');

  // ۳. افزودن به سبد خرید
  await page.click('button:has-text("افزودن به سبد")');
  await page.click('text=سبد خرید');

  // ۴. تکمیل خرید
  await page.click('button:has-text("پرداخت")');
  await page.fill('[aria-label="شماره کارت"]', '1234567890123456');
  await page.click('button:has-text("پرداخت")');

  // ۵. تأیید
  await expect(page.locator('text=پرداخت موفق')).toBeVisible();
});

// تست E2E دیگر:
// - User can register
// - User can reset password
// - Admin can view dashboard
// فقط ۵-۱۰ تست E2E برای کل پروژه!
```

