#### ۳. الگوهای تست (Templates):

```typescript
// 📁 __tests__/ComponentName.test.tsx

// ============================================
// Template: Integration Test
// ============================================
import { render, screen } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { ComponentName } from './ComponentName';

describe('ComponentName', () => {
  // ۱. Happy Path
  describe('when data is loaded successfully', () => {
    it('should display the list of items', async () => {
      render(<ComponentName />);

      await screen.findByText('Item 1');
      expect(screen.getByRole('list')).toBeVisible();
    });

    it('should allow user to interact with items', async () => {
      render(<ComponentName />);

      const button = await screen.findByRole('button', { name: /افزودن/i });
      await userEvent.click(button);

      expect(screen.getByText(/اضافه شد/i)).toBeVisible();
    });
  });

  // ۲. Error State
  describe('when an error occurs', () => {
    it('should display error message', async () => {
      // Mock API error
      server.use(
        http.get('/api/data', () => HttpResponse.error())
      );

      render(<ComponentName />);

      await screen.findByText(/خطا در دریافت اطلاعات/i);
      expect(
        screen.getByRole('button', { name: /تلاش مجدد/i })
      ).toBeVisible();
    });
  });

  // ۳. Empty State
  describe('when there is no data', () => {
    it('should display empty state', async () => {
      server.use(
        http.get('/api/data', () => HttpResponse.json([]))
      );

      render(<ComponentName />);

      await screen.findByText(/داده‌ای یافت نشد/i);
    });
  });

  // ۴. Loading State
  describe('while loading', () => {
    it('should show loading indicator', () => {
      render(<ComponentName />);

      expect(screen.getByRole('progressbar')).toBeVisible();
    });
  });

  // ۵. Accessibility
  describe('accessibility', () => {
    it('should have no accessibility violations', async () => {
      const { container } = render(<ComponentName />);

      const results = await axe(container);
      expect(results).toHaveNoViolations();
    });
  });
});
```

